    "key_shows_results_as": "نتیجه‌ها را به‌صورت 36°52′11.63″ نشان می‌دهد و DMS در نمایشگر نشان می‌دهد روشن است. زاویه‌ای را که چنین نوشته شده بچسبانید، 12°30′15″، 12°30'15\" یا 51°30′26″N: به‌تنهایی همان‌طور که نوشته شده نشان داده می‌شود و DMS روشن می‌شود. در یک معادله عددی بر حسب درجه است، و sin، cos و tan آن هر یکایی که در استفاده باشد بر حسب درجه حساب می‌شوند: sin(30°) در Rad هم 0.5 است. مبدل هم درجه، دقیقه و ثانیه را میان زاویه‌هایش دارد.",
