    "number_format_fix_sci": "قالب عدد: نمادگذاری Fix، Sci یا Eng با رقم اعشار خودکار یا 0 تا 9، و جداکنندهٔ هزارگان: 1,234.5، 1 234.5، 1.234,5 یا 1 234,5. با دو تای آخر، ممیز ویرگول است: کلید نقطه آن را می‌نویسد، و آنچه کپی و چسبانده می‌شود هم همین‌طور نوشته می‌شود.",
