    "function_keys_before_number": "کلیدهای تابع پیش از عدد، √ 9، مانند بیشتر ماشین‌حساب‌ها؛ x²، x³، x!، 1/x و % پس یا پیش از آن، 5 x² یا x² 5. کلیدی دوعددی که اول زده شود، مانند nCr، آخرین نتیجه را می‌گیرد.",
    "detached_mode_calculator_in": "وضع جدا: ماشین‌حساب در پنجرهٔ خودش. زبانهٔ «تنظیمات» را ببینید.",
    "memorizes_not_only_display": "با خاموش و روشن شدن نه تنها نمایشگر بلکه همهٔ حالت‌های دیگر را هم به خاطر می‌سپارد. حتی می‌توان پس از خاموش و روشن کردن رایانه محاسبه را ادامه داد.",
