    "copy_paste_from_to": "کپی و چسباندن از نمایشگر و به آن با Ctrl+C و Ctrl+V، یا با راست‌کلیک روی ماشین‌حساب و انتخاب «کپی» یا «چسباندن». می‌توانید یک معادلهٔ کامل، مانند 2 + 3 × sin(30)، را بچسبانید، نه فقط یک عدد.",
