    "or_ec": "یا EC",
    "and_hill_slope_drawn": "و شیب هیل آن، رسم‌شده؛ و جدول خالص‌سازی، با فعالیت ویژه، بازده و ضریب خالص‌سازی هر مرحله.",
    "lab_c_v_c": "آزمایشگاه: C₁V₁ = C₂V₂ و رقیق‌سازی پیاپی، لوله‌ها رسم‌شده؛ ساختن محلولی با یک مولاریته، از جرم مولی یا فرمول، یک درصد یا یک ذخیره؛ شمارش سلول روی هموسیتومتر، با زنده‌مانی و کاشت؛ رشد و زمان دو برابر شدن، و OD",
    "colonies_and_cfu_ml": "؛ کلنی‌ها و CFU/mL، پلیت رسم‌شده؛ RPM و g سانتریفیوژ؛ مستر میکس PCR؛ qPCR با ΔΔCt و فافل، و منحنی استاندارد و بازده آن؛ میانگین ± 2 SE گروه‌ها، با میله‌های خطا؛ R",
    "of_chromatography_microscope_s": "کروماتوگرافی؛ بزرگ‌نمایی و میدان دید میکروسکوپ؛ اندازهٔ یک باند از ژل، DNA یا پروتئین در SDS-PAGE؛ بازده ترانسفورماسیون؛ کاشت پلیت‌ها، پلیت رسم‌شده؛ MOI، و سلول‌های آلوده طبق پواسون؛ رادیوایزوتوپ‌ها، واپاشی و حفاظشان؛ و بافرها، آنچه باید وزن کرد و چه مقدار اسید یا باز باید افزود.",
    "cells_water_potential_and": "سلول‌ها: پتانسیل آب، و جهت حرکت آب؛ اسمولاریته و تونیسیته، گلبول قرمز رسم‌شده؛ نسبت سطح به حجم؛ Q",
    "diffusion_by_fick_s": "؛ انتشار طبق قانون فیک، و زمان انتشار؛ پتانسیل‌های غشا طبق نرنست و گلدمن، روی مقیاسی از mV؛ انرژی آزاد و K؛ برون‌ده قلب و فشار خون، موجش رسم‌شده؛ و تنفس، ATP آن و ضریب تنفسی.",
    "health_diagnostic_tests_their": "سلامت: آزمون‌های تشخیصی، حساسیت، ویژگی و ارزش‌های پیش‌بینی‌شان، هزار نفر رسم‌شده؛ نسبت خطر و نسبت شانس با بازه‌های 95% و تعداد لازم برای درمان؛ همه‌گیری طبق SIR، و ایمنی جمعی؛ اکسیژن و هموگلوبین، جابه‌جایی بور رسم‌شده؛ پتانسیل عمل طبق هاجکین-هاکسلی؛ کلیه‌ها، eGFR طبق CKD-EPI 2021، کلیرانس و اسمولالیته؛ BMI و انرژی؛ و سطح دارو در طول دوزها. برای یادگیری، نه مراقبت.",
    "ecology_population_growth_exponential": "بوم‌شناسی: رشد جمعیت، نمایی و لجستیک؛ شکارچی و شکار طبق لوتکا-ولترا، چرخه‌هایشان رسم‌شده؛ نشان‌گذاری و بازگیری، طبق لینکلن-پیترسن و چپمن؛ تنوع طبق سیمپسون و شانون؛ جدول‌های زندگی و منحنی بقای آن‌ها؛ هرم‌های انرژی؛ تولید اولیه با بطری‌های روشن و تاریک؛ انتخاب طبیعی و رانش ژنتیکی، نسل به نسل؛ ماتریس‌های لزلی؛ رقابت طبق لوتکا-ولترا، با خط‌های هم‌رشد؛ منحنی‌های گونه-مساحت، رقیق‌سازی و Chao1؛ درخت‌ها با UPGMA و اتصال همسایه، از فاصله‌ها یا توالی‌های هم‌تراز، رسم‌شده؛ و ساعت مولکولی، طبق جوکس-کانتور و کیمورا.",
    "in_f_x_formulas": "در f(x)، فرمول‌های زیست‌شناسی و سلامت، هر کدام با «در زیست‌شناسی» برای باز کردن کارتش؛ و در مبدل، مولاریته، غلظت جرمی، مقدار ماده، جرم مولکولی، طول توالی، فعالیت آنزیم، شمار در حجم و دوزهای پرتو.",
