    "display_shows_equation_as": "نمایشگر معادله را همان‌طور که وارد می‌کنید نشان می‌دهد، پس همیشه عملی را که انجام خواهد شد می‌بینید. روی علامت مساوی کلیک کنید تا نمایشگر نتیجه را نشان دهد، با معادلهٔ کامل در خط کوچک بالای آن. دکمهٔ پرانتز باز تا وقتی همهٔ عبارت‌های پرانتزی بسته نشده‌اند حلقه‌ای دورش دارد.",
    "if_equation_gets_too": "اگر معادله برای نمایشگر بیش از حد بلند شود، اول قلمش کوچک‌تر می‌شود. پس از آن، خط را فشار دهید، لحظه‌ای ثابت نگه دارید، سپس به چپ یا راست بکشید تا بقیه را ببینید؛ نقطه‌ها (…) سمتی را که بیشتر پنهان است نشان می‌دهند. کشیدن بدون نگه‌داشتن بخشی از آن را انتخاب می‌کند. روی صفحهٔ لمسی کشیدن آن را می‌لغزاند و نگه‌داشتن انتخاب می‌کند.",
    "if_calculation_not_possible": "اگر محاسبه‌ای ممکن نباشد (برای نمونه 1 ÷ 0)، نمایشگر «خطا» نشان می‌دهد و خط بالا معادله‌ای را که باعثش شده.",
    "calculator_uses_algebraic_method": "این ماشین‌حساب از روش ورود جبری استفاده می‌کند که به شما اجازه می‌دهد عبارت‌های ریاضی را به همان ترتیبی که به‌صورت جبری نوشته می‌شوند وارد کنید (PEMDAS / AOS™).",
    "pemdas_parentheses_exponents_multiplication": "PEMDAS: «پرانتز، توان، ضرب یا تقسیم، و جمع یا تفریق». ضرب و تقسیم هم‌رتبه‌اند. جمع و تفریق هم.",
