    "keys_same_on_keyboard": "کلیدها روی صفحه‌کلیدی بدون حروف لاتین، عربی، عبری، روسی، یونانی، همان‌اند: هر کلید همان چیزی را می‌دهد که کلید هم‌جایش روی صفحه‌کلید آمریکایی می‌دهد، پس [s] روی کلید س همان sin است و Shift+A،",
    "and_digits_work_as": "و رقم‌ها مانند هر صفحه‌کلید دیگری کار می‌کنند. کادر یک پنل، مبدل، فرمول یا نمودار، آن‌ها را به همین شیوه می‌گیرد: ٥ عدد 5 را می‌نویسد و Shift+ش حرف A را، و عددی که با ٣٫٥ چسبانده شود 3.5 خوانده می‌شود.",
    "see_below_keyboard_shortcuts": "میان‌برهای صفحه‌کلید هر دکمهٔ ماشین‌حساب را در پایین در [کروشه] ببینید.",
