    "ctrl_v_pastes_number": "Ctrl+V یک عدد را می‌چسباند (1,234.5، 1.234,5 و 1 234,5 همه 1234.5 خوانده می‌شوند؛ 1.234 به‌تنهایی با ممیزی که تنظیمات تعیین کرده خوانده می‌شود، و $1,200 یا 5 USD فقط به‌صورت عدد) یا یک معادلهٔ کامل، مانند 2 + 3 × sin(30) یا sqrt(16) + 2^3. اگر متن چسبانده‌شده علامت مساوی داشته باشد، فوراً حساب می‌شود.",
