    "right_click_display_for": "روی نمایشگر راست‌کلیک کنید تا منویی با «برش»، «کپی» و «چسباندن» بیاید، و «بازنشانی همه» که ماشین‌حساب را از نو آغاز می‌کند: معادله و حافظه پاک، 2nd، کسرها و °′″ خاموش، Rad، و آنچه در آمار، جست‌وجوی فرمول‌ها، مبدل، نمودار، حل‌کننده و عددها نوشته شده پاک؛ تاریخچه و متغیرهایش می‌مانند. «کپی» بخش انتخاب‌شدهٔ نمایشگر را می‌گیرد، وگرنه نتیجه را. بار اولی که از «چسباندن» آنجا استفاده کنید، مرورگر می‌خواهد به ماشین‌حساب اجازه دهید آنچه کپی کرده‌اید را بخواند؛ Ctrl+V بدون آن کار می‌کند. تاریخچه، فرمول‌ها، مبدل و آمار هم این منو را دارند: «برش»، «کپی»، «چسباندن» و «انتخاب همه» در کادری که می‌نویسید، «کپی» و «درج» روی یک مقدار.",
