    "history_click_clock_at_2": "تاریخچه: روی ساعت بالا سمت چپ نمایشگر کلیک کنید تا محاسبه‌هایی را که با '=' تمام کرده‌اید ببینید. نشانگر را روی یک معادله یا نتیجه ببرید تا دو دکمه‌اش در سمت چپ ظاهر شوند: «درج» معادله را دوباره وارد می‌کند تا تغییرش دهید یا با '=' تمامش کنید، یا نتیجه را به‌صورت عدد در معادله‌ای که می‌نویسید می‌گذارد؛ «کپی» آن را کپی می‌کند. محاسبه‌ای با",
