    "calculator_operates_with_precision": "این ماشین‌حساب با دقت حدود ۱۵ رقم معنادار (فقط) کار می‌کند. این به دلیل شیوهٔ کار JavaScript با اعداد ممیز شناور است.",
    "isn_t_actually_javascript": "این در واقع ویژگی JavaScript نیست، بلکه ویژگی شیوه‌ای است که استاندارد IEEE 754 برای نگه‌داری اعداد ممیز شناور در حافظه تعریف می‌کند. JavaScript هر عدد را یکی از این مقدارهای ۶۴ بیتی می‌خواهد و هر زبانی که از آن‌ها استفاده کند، مانند C، Java یا Python، نیز از این «ویژگی» رنج می‌برد.",
    "results_shown_with_13": "نتیجه‌ها با ۱۳ رقم معنادار نشان داده می‌شوند تا این خطاهای گرد کردن ریز دیده نشوند: 0.1 + 0.2 عدد 0.3 را نشان می‌دهد، نه 0.30000000000000004. زاویه‌ها به درجه، جایی که باید، مقدار دقیق می‌دهند: sin 180 برابر 0 و cos 60 برابر 0.5 است.",
    "problem_javascript_uses_64": "مشکل این است که JavaScript برای نگه‌داری هر عدد ۶۴ بیت داده به کار می‌برد که می‌تواند 18446744073709551616 الگوی بیتی گوناگون را نگه دارد: ۱ بیت برای علامت، ۱۱ بیت برای توان و ۵۲ بیت برای رقم‌ها. این مقدارهایی از حدود –1.7976931348623157e+308 تا 1.7976931348623157e+308 را در بر می‌گیرد؛ کوچک‌ترین عدد نرمال 2.2250738585072014e–308 است و عددهای باز هم کوچک‌تر تا 5e–324.",
    "smaller_precision_value_with": "مقداری با دقت کمتر که بخشی از بیت‌هایش توان است، راهی است که این بازه را جا می‌دهد (این کار با ۱۶ بیت هم شدنی است، با بازه‌ای کوچک‌تر و دقتی کمتر). نتیجه این است که هر مقدار در این بازه را می‌تواند تقریب بزند، اما همه را دقیقاً نمایش نمی‌دهد، چون در اعداد حقیقی میان هر دو مقدار بی‌نهایت مقدار وجود دارد.",
    "as_part_of_your": "در جریان محاسبهٔ شما، نمایش درونی مقدار از دقت موجود فراتر می‌رود و به جای مقدار دقیق، تقریبی از آن به دست می‌آید.",
    "for_schools_and_organizations": "برای مدرسه‌ها و سازمان‌ها",
