    "niobium_used_as_alloying": "نیوبیم به‌عنوان عامل آلیاژساز و در جواهرسازی به کار می‌رود، اما شاید جالب‌ترین کاربردهایش در زمینهٔ ابررسانایی باشد.",
    "name_derives_from_greek_13": "نام از نیوبه، شخصیت اسطوره‌ای یونانی و دختر تانتالوس، آمده است، زیرا در آغاز گمان می‌رفت نیوبیم و تانتال یکسان‌اند.",
    "grey_metal_bluish_when": "فلز خاکستری، مایل به آبی هنگام اکسید شدن",
    "molybdenum": "مولیبدن",
    "molybdenum_has_high_melting": "مولیبدن نقطهٔ ذوب بالایی دارد و برای ساخت الکترودهای کوره‌های شیشهٔ برقی به کار می‌رود. برخی رشته‌های الکتریکی نیز از مولیبدن ساخته می‌شوند.",
    "name_derives_from_greek_14": "نام از واژهٔ یونانی molybdos به معنای «سرب» آمده است. پیشینیان واژهٔ «سرب» را برای هر کانی سیاهی که روی کاغذ رد بگذارد به کار می‌بردند.",
    "grey_metal": "فلز خاکستری",
    "technetium": "تکنسیم",
    "small_amounts_of_technetium": "مقدار کمی تکنسیم می‌تواند خوردگی فولاد را کند کند، هرچند به دلیل پرتوزایی تکنسیم این محافظت فقط در سامانه‌های بسته شدنی است.",
    "technetium_was_first_artificially": "تکنسیم نخستین عنصری بود که به‌طور مصنوعی ساخته شد. در سال ۱۹۳۷ به دست کارلو پریه و امیلیو سگره جدا شد.",
    "ruthenium": "روتنیم",
    "ruthenium_primarily_used_as": "روتنیم بیشتر به‌عنوان عامل آلیاژساز به کار می‌رود. افزودن ۰٫۱٪ روتنیم به تیتانیم آن را ۱۰۰ برابر در برابر خوردگی مقاوم‌تر می‌کند.",
    "name_derives_from_latin_17": "نام از واژهٔ لاتین ruthenia، نام کهن روسیه، آمده است.",
    "rhodium": "رودیم",
    "rhodium_used_to_make": "رودیم برای ساخت اتصال‌های الکتریکی، در جواهرسازی و در مبدل‌های کاتالیستی به کار می‌رود، اما بیشتر به‌عنوان عامل آلیاژساز در مواد دیگر مانند پلاتین و پالادیم استفاده می‌شود.",
    "name_derives_from_greek_15": "نام از واژهٔ یونانی rhodon به معنای گل سرخ آمده است، به دلیل رنگ گل‌سرخی محلول‌های رقیق نمک‌هایش.",
    "palladium": "پالادیم",
    "palladium_used_to_make": "پالادیم برای ساخت فنر ساعت، ابزارهای جراحی، اتصال‌های الکتریکی و پرکردگی و روکش دندان به کار می‌رود.",
    "name_derives_from_second": "نام از دومین سیارک بزرگ منظومهٔ خورشیدی، پالاس، آمده است (که به نام الههٔ خرد و هنر، پالاس آتنه، نام‌گذاری شد).",
    "silver": "نقره",
    "silver_and_silver_compounds": "نقره و ترکیب‌هایش کاربردهای فراوانی دارند.",
    "name_derives_from_anglo_2": "نام از واژه‌های انگلوساکسون seofor و siolfur با ریشه‌ای ناشناخته آمده است.",
    "lustrous_white_metal": "فلز سفید براق",
    "cadmium": "کادمیم",
    "cadmium_poisonous_metal_and": "کادمیم فلزی سمی است و به همین دلیل کاربردش تا اندازه‌ای محدود است. مانند روی، کادمیم را می‌توان روی مواد دیگر آبکاری کرد تا از خوردگی محافظت شوند.",
    "name_derives_from_greek_16": "نام از واژهٔ یونانی kadmeia به معنای «کالامین» (روی کربنات) آمده است که در طبیعت به‌صورت ناخالصی همراه آن یافت شد.",
    "silvery_bluish_grey_metal": "فلز خاکستری مایل به آبی نقره‌ای",
    "indium": "ایندیم",
    "indium_used_to_coat": "ایندیم برای روکش یاتاقان‌های موتورهای پرسرعت به کار می‌رود، زیرا روغن روان‌کننده را یکنواخت پخش می‌کند. ایندیم برای آلایش ژرمانیم در ساخت ترانزیستور به کار می‌رود.",
    "name_derives_from_term": "نام از واژهٔ «indigo» آمده است، به دلیل خط آبی نیلی در طیف جرقهٔ این عنصر.",
    "body_centred_tetragonal": "چهارگوشی مرکزپر",
    "silvery_lustrous_grey_metal": "فلز خاکستری براق نقره‌ای",
    "tin": "قلع",
    "tin_resists_corrosion_and": "قلع در برابر خوردگی مقاوم است و به‌عنوان روکش محافظ روی فلزهای دیگر به کار می‌رود. قوطی‌های حلبی شاید آشناترین نمونهٔ این کاربرد باشند. قوطی حلبی در واقع از فولاد ساخته می‌شود.",
    "name_derives_from_anglo_3": "نام از واژهٔ انگلوساکسون tin با ریشه‌ای ناشناخته آمده است. نماد Sn از واژهٔ لاتین stannum برای آلیاژهای دارای سرب آمده است.",
    "white_tin_paramagnetic_grey": "قلع سفید پارامغناطیس؛ قلع خاکستری دیامغناطیس",
    "white_body_centred_tetragonal": "سفید (β): چهارگوشی مرکزپر؛ خاکستری (α): مکعبی الماسی",
    "silvery_white_white_tin": "سفید نقره‌ای (قلع سفید)؛ خاکستری (قلع خاکستری)",
    "antimony": "آنتیموان",
    "antimony_brittle_metal_and": "آنتیموان فلزی شکننده و رسانای ضعیف گرما و برق است. آنتیموان بسیار خالص برای ساخت برخی قطعه‌های نیمه‌رسانا، مانند دیودها و آشکارسازهای فروسرخ، به کار می‌رود.",
    "name_derives_from_greek_17": "نام از واژه‌های یونانی anti + monos به معنای «نه تنها» یا «نه یکی» آمده است، زیرا در ترکیب‌های فراوانی یافت می‌شد.",
    "silvery_lustrous_grey": "خاکستری براق نقره‌ای",
    "sumerians": "سومریان",
    "tellurium": "تلوریم",
    "tellurium_semiconductor_and_frequently": "تلوریم نیمه‌رسانا است و اغلب با مس، قلع، طلا یا نقره آلاییده می‌شود. برای رنگ کردن شیشه و سرامیک نیز به کار می‌رود و یکی از اجزای اصلی چاشنی‌های انفجاری است.",
    "name_derives_from_latin_18": "نام از تلوس، الههٔ رومی زمین، آمده است.",
    "silvery_lustrous_grey_brown": "خاکستری براق نقره‌ای؛ قهوه‌ای-سیاه به‌صورت پودر",
    "iodine": "ید",
    "iodine_used_as_test": "ید برای آزمایش نشاسته به کار می‌رود و در تماس با آن آبی تیره می‌شود.",
    "name_derives_from_greek_18": "نام از واژهٔ یونانی iodes به معنای «بنفش» آمده است، به دلیل بخارهای بنفشش.",
    "lustrous_grey_black_solid": "جامد خاکستری-سیاه براق؛ گاز بنفش",
