    "since_only_few_atoms": "چون تاکنون تنها چند اتم سیبورگیم ساخته شده، اکنون جز در پژوهش علمی پایه کاربردی ندارد.",
    "seaborgium_was_first_produced": "سیبورگیم نخستین بار در سال ۱۹۷۴ به دست گروهی از دانشمندان به سرپرستی آلبرت گیورسو در آزمایشگاه لارنس برکلی، کالیفرنیا، ساخته شد.",
