    "since_only_few_atoms_2": "چون تاکنون تنها چند اتم بوریم ساخته شده، اکنون جز در پژوهش علمی پایه کاربردی ندارد.",
    "first_produced_in_1976": "نخستین بار در سال ۱۹۷۶ به دست دانشمندان مؤسسهٔ مشترک پژوهش‌های هسته‌ای در دوبنا، روسیه، ساخته شد و بعدها در سال ۱۹۸۱ پیتر آرمبروستر،… آن را تأیید کردند",
    "hassium": "هاسیم",
    "since_only_small_amounts_4": "چون تاکنون تنها مقدار کمی هاسیم تولید شده، اکنون جز در پژوهش علمی پایه کاربردی ندارد.",
    "hassium_was_first_produced": "هاسیم نخستین بار در سال ۱۹۸۴ به دست پیتر آرمبروستر، گوتفرید مونتسنبرگ و گروهشان در Gesellschaft für Schwerionenforschung در دارمشتات، آلمان، ساخته شد.",
