    "meitnerium_was_first_produced": "مایتنریم نخستین بار در سال ۱۹۸۲ به دست پیتر آرمبروستر، گوتفرید مونتسنبرگ و گروهشان در Gesellschaft für Schwerionenforschung در دارمشتات، آلمان، ساخته شد.",
