    "darmstadtium_was_first_produced": "دارمشتادیم نخستین بار در ۹ نوامبر ۱۹۹۴ به دست پیتر آرمبروستر، گوتفرید مونتسنبرگ و گروهشان در Gesellschaft für Schwerionenforschung در دارمشتات، آلمان، ساخته شد.",
