    "roentgenium_was_first_produced": "رونتگنیم نخستین بار در اواخر ۱۹۹۴ به دست پیتر آرمبروستر، گوتفرید مونتسنبرگ و گروهشان در Gesellschaft für Schwerionenforschung در دارمشتات، آلمان، ساخته شد.",
