    "copernicium_was_first_produced": "کوپرنیسیم نخستین بار در ۹ فوریهٔ ۱۹۹۶ به دست پیتر آرمبروستر، گوتفرید مونتسنبرگ و گروهشان در Gesellschaft für Schwerionenforschung در دارمشتات، آلمان، ساخته شد.",
