    "on_july_23_2004": "در ۲۳ ژوئیهٔ ۲۰۰۴ دانشمندان مرکز نیشینای RIKEN برای علوم مبتنی بر شتاب‌دهنده در واکو، ژاپن، نخستین دو اتم این عنصر را ساختند…",
