    "on_february_2_2004": "در ۲ فوریهٔ ۲۰۰۴ دانشمندان مؤسسهٔ مشترک پژوهش‌های هسته‌ای در دوبنا، روسیه، همراه با دانشمندانی از وزارت… ایالات متحده",
    "livermorium": "لیورموریم",
    "since_only_few_atoms_9": "چون تاکنون تنها چند اتم لیورموریم تولید شده، اکنون جز در پژوهش علمی پایه کاربردی ندارد.",
    "on_december_6_2000": "در ۶ دسامبر ۲۰۰۰ دانشمندان مؤسسهٔ مشترک پژوهش‌های هسته‌ای در دوبنا، روسیه، همراه با دانشمندان آزمایشگاه ملی لارنس لیورمور وزارت انرژی ایالات متحده، ساخت لیورموریم را اعلام کردند.",
